(() => {
  'use strict';
  const P = window.Portal;
  if (!P) return;
  const { e, icon } = P;
  const demos = {
    estate1: { welcome: 'Välkommen till ditt nya hem.', intro: 'Fastighetsbolaget registrerar inflyttningsunderlag och bifogar fullmakter. Kraftringen tar över elfrågorna och återkopplar till fastighetsbolaget.', address: 'Exempelgatan 4', postcode: '222 22', city: 'Lund', properties: ['Exempelgatan 4 · Lund', 'Demovägen 12 · Malmö'] },
    estate2: { welcome: 'En enklare start i ditt nya hem.', intro: 'Fastighetsbolaget samlar inflyttningsunderlag och fullmakter. Kraftringen hjälper till med elen och återkopplar till fastighetsbolaget.', address: 'Testallén 8', postcode: '252 22', city: 'Helsingborg', properties: ['Testallén 8 · Helsingborg', 'Exempeltorget 2 · Landskrona'] }
  };
  let query = '', filter = 'all';
  const partner = () => P.getPartner?.(P.partner) || { id: P.partner, name: P.partners[P.partner] || 'Fastighetspartner', type: 'property' };
  const date = value => value && !Number.isNaN(new Date(value + (value.length === 10 ? 'T12:00:00' : '')).getTime()) ? new Intl.DateTimeFormat('sv-SE', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(value + (value.length === 10 ? 'T12:00:00' : ''))) : 'Ej angivet';
  const note = text => `<p class="property-note">${icon('shield')}<span>${e(text)}</span></p>`;
  function init() {
    if (!P.state.propertySettings || typeof P.state.propertySettings !== 'object') P.state.propertySettings = {};
    for (const item of P.partnerRegistry.filter(item => item.type === 'property')) {
      if (P.state.propertySettings[item.id]) continue;
      const data = demos[item.id];
      P.state.propertySettings[item.id] = data ? { ...data, properties: [...data.properties] } : {
        welcome: 'En enklare inflyttning.',
        intro: 'Ni registrerar inflyttningsunderlag och bifogar fullmakter. Kraftringen tar över elfrågorna och återkopplar till er.',
        address: '', postcode: '', city: '', properties: []
      };
    }
    if (!Array.isArray(P.state.moveins)) P.state.moveins = [];
    P.state.propertyDemoSeeded = true;
  }
  P.initPropertyDemo = init;
  init();
  const registrations = (partnerId = P.partner) => P.moveinService?.rows(partnerId) || P.state.moveins.filter(row => row.partner === partnerId).sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));
  const status = row => P.moveinService?.statusLabel(row) || 'Underlag sparat';
  const ready = row => row.handoverStatus === 'draft' && !!P.moveinService?.canForward(row);
  const incomplete = row => row.handoverStatus === 'draft' && !P.moveinService?.canForward(row);
  const stats = rows => ({ ready: rows.filter(ready).length, underway: rows.filter(row => ['submitted', 'handling'].includes(row.handoverStatus)).length, needs: rows.filter(row => row.handoverStatus === 'needs_info').length, done: rows.filter(row => row.handoverStatus === 'confirmed').length });
  function intake(mode = 'choice') { P.propertyIntake?.open(mode, P.partner); }
  function bindDetails() {
    document.querySelectorAll('[data-movein-detail]').forEach(button => button.onclick = () => P.moveinService?.open(button.dataset.moveinDetail));
    document.querySelectorAll('[data-property-filter]').forEach(button => button.onclick = () => { filter = button.dataset.propertyFilter; P.go('property-registrations'); });
    document.querySelectorAll('[data-property-intake]').forEach(button => button.onclick = () => intake(button.dataset.propertyIntake));
  }
  function registrationTable(rows, compact = false) {
    return rows.length ? `<div class="table-wrap property-table-wrap"><table class="property-table"><thead><tr><th>Hyresgäst · exempel</th><th>Bostad</th><th>Inflyttning</th><th>Ärende</th>${compact ? '' : '<th></th>'}</tr></thead><tbody>${rows.map(row => `<tr><td data-label="Hyresgäst"><button class="text-button" data-movein-detail="${e(row.id)}">${e(row.name)}</button><span class="property-table-sub">${e(row.email)}</span></td><td data-label="Bostad">${e(row.address)}${row.apartment ? `<span class="property-table-sub">Lägenhet ${e(row.apartment)}</span>` : ''}</td><td data-label="Inflyttning">${e(date(row.moveDate))}</td><td data-label="Ärende"><span class="pill property-status-${e(row.handoverStatus || 'draft')}">${e(status(row))}</span>${incomplete(row) ? '<span class="property-table-sub">Underlag eller fullmakt behöver kompletteras</span>' : ''}</td>${compact ? '' : `<td class="property-row-action"><button class="btn btn-secondary btn-small" data-movein-detail="${e(row.id)}" aria-label="Öppna ärendet för ${e(row.name)}">${ready(row) ? 'Förmedla' : 'Öppna'} ${icon('arrow')}</button></td>`}</tr>`).join('')}</tbody></table></div>` : '<div class="empty property-empty"><span class="property-kpi-icon">' + icon('home') + '</span><strong>Inga ärenden i den här vyn ännu.</strong><p>Ladda upp en Excel-fil eller registrera en inflyttning för hand.</p><button class="btn btn-secondary" data-property-intake="choice">Registrera inflyttning ' + icon('arrow') + '</button></div>';
  }
  const flow = () => `<section class="property-how property-service-flow"><div>${icon('file')}<h3>Ni registrerar inflyttningen</h3><p>Ladda upp en Excel-fil för flera inflyttare eller fyll i en inflyttning för hand.</p></div><div>${icon('shield')}<h3>Ni bifogar fullmakterna</h3><p>Samla underlag och fullmakter på respektive ärende.</p></div><div>${icon('arrow')}<h3>Ni förmedlar till Kraftringen</h3><p>Granska uppgifterna och lämna över ärenden som är klara.</p></div><div>${icon('bolt')}<h3>Vi hjälper till med elen</h3><p>Kraftringen handlägger elfrågorna och återkopplar till er. Hyresgästen använder inte portalen.</p></div></section>`;
  const homeArt = () => `<div class="property-home-art" aria-hidden="true"><span class="property-home-halo"></span><div class="property-home-building"><div class="property-home-roof"></div><div class="property-home-windows"><i></i><i></i><i></i><i></i><i></i><i></i></div><span class="property-home-door"></span></div><span class="property-home-spark property-home-spark-one">${icon('bolt')}</span><span class="property-home-spark property-home-spark-two">${icon('file')}</span><div class="property-home-card"><span>${icon('bolt')}</span><div><strong>Ni samlar underlaget.</strong><small>Kraftringen hjälper till med elen.</small></div>${icon('check')}</div><div class="property-home-caption">Ett enkelt arbetssätt mellan er och Kraftringen.</div></div>`;
  const intakeCards = () => `<section class="property-intake-options" aria-labelledby="property-intake-title"><div class="property-intake-heading"><span class="property-eyebrow">VÄLJ DET SOM PASSAR ER</span><h2 id="property-intake-title">Två sätt att registrera inflyttningar.</h2></div><div class="property-intake-grid"><button type="button" class="property-intake-card property-intake-excel" data-property-intake="import"><span class="property-intake-icon">${icon('file')}</span><span class="property-intake-card-copy"><small>FLERA INFLYTTARE</small><strong>Ladda upp Excel</strong><span>Granska inflyttningslistan och bifoga fullmakter till ärendena.</span><span class="property-intake-link">Välj Excel-fil ${icon('arrow')}</span></span></button><button type="button" class="property-intake-card" data-property-intake="manual"><span class="property-intake-icon">${icon('edit')}</span><span class="property-intake-card-copy"><small>EN INFLYTTNING I TAGET</small><strong>Fyll i för hand</strong><span>Registrera bostad och hyresgäst direkt. Bifoga fullmakten i samma flöde.</span><span class="property-intake-link">Registrera inflyttning ${icon('arrow')}</span></span></button></div></section>`;
  function renderOverview() {
    init();
    const rows = registrations(), counts = stats(rows);
    return `<div class="property-dashboard"><div class="page-head"><div><span class="eyebrow">FASTIGHETSPARTNER / ${e(partner().name)}</span><h1>Inflyttningsservice</h1><p>Ni registrerar inflyttningen. Kraftringen hjälper till med elen.</p></div><button class="btn btn-secondary" data-go="property-registrations">Alla ärenden ${icon('arrow')}</button></div><section class="property-hero property-hero-compact"><div class="property-hero-copy"><span class="property-eyebrow">EN ENKLARE INFLYTTNING</span><h2>Samla underlaget.<br>Låt oss ta nästa steg.</h2><p>Fastighetsbolaget sköter registrering och fullmakter. Kraftringen tar emot underlaget, hanterar elfrågorna och återkopplar till er.</p><div class="property-hero-label">${icon('home')} Hyresgästen behöver inte logga in eller fylla i något här.</div></div>${homeArt()}</section>${intakeCards()}${P.propertyResults?.renderSummary?.(P.partner) || ''}<div class="property-kpis property-service-kpis"><article class="card"><span class="property-kpi-icon">${icon('file')}</span><div><span>Klara att förmedla</span><strong>${counts.ready}</strong><small><button class="text-button" data-property-filter="ready">Öppna underlag ${icon('arrow')}</button></small></div></article><article class="card"><span class="property-kpi-icon">${icon('bolt')}</span><div><span>Hos Kraftringen</span><strong>${counts.underway}</strong><small><button class="text-button" data-property-filter="underway">Följ ärenden ${icon('arrow')}</button></small></div></article><article class="card"><span class="property-kpi-icon">${icon('edit')}</span><div><span>Behöver kompletteras</span><strong>${counts.needs}</strong><small><button class="text-button" data-property-filter="needs_info">Se återkoppling ${icon('arrow')}</button></small></div></article><article class="card"><span class="property-kpi-icon">${icon('check')}</span><div><span>Återkoppling klar · demo</span><strong>${counts.done}</strong><small><button class="text-button" data-property-filter="confirmed">Visa återkoppling ${icon('arrow')}</button></small></div></article></div><div class="property-next-step">${P.workbench?.render({ limit: 3, title: 'Det här behöver er uppmärksamhet' }) || ''}</div><section class="card property-queue-card"><div class="section-title"><div><span class="property-eyebrow">ÖVERLÄMNING & ÅTERKOPPLING</span><h2>Era senaste inflyttningsärenden</h2></div><button class="text-button" data-go="property-registrations">Visa alla ${icon('arrow')}</button></div>${registrationTable(rows.slice(0, 4), true)}${note(`${rows.length} ärenden i testet. Registrering och serviceärenden skapar inte automatiskt elavtal eller kickback.`)}</section><details class="property-service-explainer"><summary>Så fungerar samarbetet <span>Från ert underlag till vår återkoppling</span></summary>${flow()}<div class="property-business-separation">${icon('home')}<p><strong>Hyresgästens el är en egen kundaffär.</strong> Fastighetsbolagets egen elförbrukning hanteras separat från inflyttningsservicen.</p></div></details></div>`;
  }
  P.register('property-overview', { render: renderOverview, bind: bindDetails });
  const filterOptions = [['all', 'Alla ärenden'], ['ready', 'Klara att förmedla'], ['underway', 'Hos Kraftringen'], ['needs_info', 'Behöver kompletteras'], ['confirmed', 'Återkoppling klar · demo'], ['incomplete', 'Ofullständiga underlag']];
  const matchesFilter = row => filter === 'all' || filter === 'ready' && ready(row) || filter === 'underway' && ['submitted', 'handling'].includes(row.handoverStatus) || filter === 'incomplete' && incomplete(row) || row.handoverStatus === filter;
  function renderRegistrations() {
    const rows = registrations().filter(row => matchesFilter(row) && `${row.name} ${row.address} ${row.city} ${row.email}`.toLocaleLowerCase('sv').includes(query.toLocaleLowerCase('sv')));
    const events = P.moveinService?.activityFor(P.partner).slice(0, 5) || [];
    return `<div class="page-head"><div><span class="eyebrow">${e(partner().name)}</span><h1>Inflyttningsärenden</h1><p>Samla underlag och fullmakter. Förmedla ärenden och följ Kraftringens återkoppling.</p></div><button class="btn btn-primary" data-property-intake="choice">Registrera inflyttning ${icon('arrow')}</button></div><section class="card"><div class="property-list-toolbar"><div class="field"><label for="property-query">Sök hyresgäst eller adress</label><input id="property-query" type="search" placeholder="Namn, adress eller ort" value="${e(query)}"></div><div class="field"><label for="property-filter">Visa ärenden</label><select id="property-filter">${filterOptions.map(([value, label]) => `<option value="${value}"${filter === value ? ' selected' : ''}>${label}</option>`).join('')}</select></div><span class="pill">${rows.length} ärenden</span></div>${registrationTable(rows)}${note('Test med exempeluppgifter och exempelfiler. Inget underlag skickas externt och ingen verklig fullmakt verifieras här.')}</section>${events.length ? `<section class="card property-shared-activity"><div class="section-title"><h2>Senaste återkoppling och händelser</h2></div><div class="activity-list">${events.map(event => `<div class="activity-row"><span class="activity-icon">${icon('file')}</span><span><small>${e(date(event.at))} · ${e(event.name)}</small><strong>${e(event.text)}</strong></span></div>`).join('')}</div></section>` : ''}`;
  }
  P.register('property-registrations', { render: renderRegistrations, bind: () => {
    document.querySelector('#property-query').oninput = event => { query = event.target.value; const pos = event.target.selectionStart; P.render(); const input = document.querySelector('#property-query'); input.focus(); input.setSelectionRange(pos, pos); };
    document.querySelector('#property-filter').onchange = event => { filter = event.target.value; P.render(); };
    bindDetails();
  } });
})();
